---处理参数
---goodsId integer 核心道具id, 根据此参数初始化页签选择
function GroceryCoreExchangeDialog:InitArgument()
    local parameters = self.controller.Argument.parameters
    if not parameters then return end
    
    local goodsId = checkInt(parameters.goodsId)
    for i, v in ipairs(CoreConfigs) do
        if v == goodsId then
            self:SetSelectedIndex(i)
            self:RefreshCurrencyBar()
            break
        end
    end
end

function GroceryCoreExchangeDialog:InitTabData()
    local tabData = {}
    for i, v in ipairs(CoreConfigs) do
        local goodsVo = GoodsConfMgrIns:GetGoodsVoById(v)
        local data = {
            index = i,
            text = goodsVo.name,
            selectImgPath = goodsVo.photoPath,
            func = Bind(self, self.TabOnClickHandler)
        }
        table.insert(tabData, data)
    end
    self:SetTabData(tabData)
end

function GroceryCoreExchangeDialog:InitCoreData()
    local cores = {}
    local totalData = BackpackComponent:GetGoodsByTypeId(Constants.IDType.GoodsSameCard)
    for _, v in ipairs(totalData) do
        if checkInt(v.num) > 0 then
            if cores[checkInt(v.vo.quality)] then
                table.insert(cores[checkInt(v.vo.quality)], v)
            else
                cores[checkInt(v.vo.quality)] = {v}
            end
        end
    end
    
    local coreData = {}
    for _, v in ipairs(CoreConfigs) do
        local quality = CoreType2Quality[v]
        local list = checkTable(cores[quality])
        table.sort(list, function(a, b)
            local cardIdA = a.vo.cardId
            local cardIdB = b.vo.cardId
            local isMaxA = self:CheckCoreMax(cardIdA)
            local isMaxB = self:CheckCoreMax(cardIdB)
            if isMaxA ~= isMaxB then
                return isMaxA
            else
                return checkInt(a.goodsId) < checkInt(b.goodsId)
            end
        end)
        table.insert(coreData, list)
    end
    
    self:SetTotalCoreData(coreData)
end

function GroceryCoreExchangeDialog:InitUI()
    self:RefreshTab()
    self:RefreshListView()
    self:RefreshRightPanel()
end
