---cell点击回调
---@param index integer 索引
---@param num integer 变动数量
function GroceryCoreExchangeDialog:CellOnClickHandler(index, num)
    if BackpackComponent:IsGoodsLocked(self:GetSelectedCoreData()[index].goodsId) then
        GameUtils.Toast(localize("物品已锁定"))
        return
    end
    
    local selectedNum = checkInt(self:GetSelectedCoreNum()[index])
    local totalNum = checkInt(self:GetSelectedCoreData()[index].num)
    if selectedNum >= totalNum then return end
    
    -- 未选中时，点击直接选中全部
    if selectedNum == 0 then
        num = totalNum
    end
    self:SelectCore(index, num)
end

