function GroceryCoreExchangeDialog:CellLockBtnOnClickHandler(index)
    local data = self:GetSelectedCoreData()[index]
    local locked = BackpackComponent:IsGoodsLocked(data.goodsId)
    GameUtils.Request(Interfaces.BackpackLock, {goodsId = data.goodsId, type = locked and 0 or 1}, function(request, response)
        BackpackComponent:SetGoodsLocked(data.goodsId, not locked)
        self:RefreshListView()
        self:RefreshRightPanel()
    end)
end

