---转换按钮点击回调
function GroceryCoreExchangeDialog:ConvertBtnOnClickHandler()
    local selectedNum = self:GetCurrentSelectedNum()
    if selectedNum == 0 then return end
    
    local convertNum = 0
    local data = self:GetSelectedCoreData()
    for k, v in pairs(self:GetSelectedCoreNum()) do
        convertNum = convertNum + checkInt(v) * checkInt(data[k].vo.effectNum)
    end
    local productConf = GoodsConfMgrIns:GetGoodsVoById(CoreConfigs[self:GetSelectedIndex()])
    local tips = localize("确认<color=#e71f55>消耗</color>以下核心转换<color=#e71f55>[_name1_x_num_]</color>吗？",{_num_ = convertNum, _name1_ = productConf.name})

    local price = {}
    local data = self:GetSelectedCoreData()
    for k, v in pairs(self:GetSelectedCoreNum()) do
        if v > 0 then
            local tmp = {goodsId = data[k].goodsId, num = v}
            table.insert(price, tmp)
        end
    end
    GameUtils.SecondConfirm
    (
            tips,
            function()
                if self._aniCo ~= nil then
                    cs_coroutine.stop(self._aniCo)
                end
                self._aniCo = cs_coroutine.start(function()
                    UIRaycastBlocker:AddCondition("GroceryCoreExchangeDialog")
                    CfUtils.PlayAnimation(self.GoodsBg, "OverseaStoreCoreExchangeDialog_Goods_Active")
                    cs_coroutine.yield_return(Yielders.GetWaitForSeconds(1.9))
                    CfUtils.PlayAnimation(self.GoodsBg, "OverseaStoreCoreExchangeDialog_Goods_Idle")
                    local consume = {}
                    for i, v in ipairs(price) do
                        consume[tostring(v.goodsId)] = v.num
                    end
                    consume = table.serialize(consume)
                    UIRaycastBlocker:RemoveCondition("GroceryCoreExchangeDialog")
                    GameUtils.Request(Interfaces.OverExchange, {consume = consume}, function(request, response)
                        local responseData = checkTable(response.data)
                        if #responseData.rewards > 0 then
                            for _, v in ipairs(price) do
                                v.num = -v.num
                            end
                            GoodsUtils.DrawRewards(price)
                            GoodsUtils.DrawRewards(responseData.rewards, true)
                            CriWareUtils.PlaySe(UISheets.UI_Menu.path, UISheets.UI_Menu.ui_shop_buy)
                            UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonRewardPop, parameters = { rewards = responseData.rewards } })
                            self:ClearSelectedCoreNum()
                            self:InitCoreData()
                            self:RefreshListView()
                            self:RefreshRightPanel()
                        end
                    end)
                end)
            end,
            nil,
            nil,
            6,
            price
    )
end
