---刷新选中列表
function GroceryCoreExchangeDialog:RefreshSelectedList()
    if next(self:GetSelectedCoreNum()) == nil then
        CfUtils.SetActive(self.ConsumeEmpty, true)
        CfUtils.SetActive(self.ConsumeContent, false)
        return
    end
    
    CfUtils.SetActive(self.ConsumeEmpty, false)
    CfUtils.SetActive(self.ConsumeContent, true)
    
    local selectedData = self:GetSelectedCoreData()
    local data = {}
    for k, num in pairs(self:GetSelectedCoreNum()) do
        table.insert(data, {data = selectedData[k], index = k, num = num})
    end
    table.sort(data, function(a, b) 
        return a.index < b.index
    end)
    self:SetSelectedListData(data)

    if not self.MaterialScrollView.IsListViewInit then
        self.MaterialScrollView:InitGridView(#data, Bind(self, self.OnMaterialListGetItemByIndex))
    else
        GameUtils.ReloadData(self.MaterialScrollView, #data)
    end
end

function GroceryCoreExchangeDialog:OnMaterialListGetItemByIndex(listView, index)
    if index < 0 then return nil end
    
    local cell = listView:NewListViewItem("GoodsDIsplayNode")
    local listData = self:GetSelectedListData()[index + 1]
    local goodsNode = cell.transform:Find('GoodNode')
    local scr = CfUtils.GetLuaScr(goodsNode, GroceryConstants.ScrPath.GoodNodeMB)
    if isNotNull(scr) then
        scr:Reload({ goodsId = listData.data.goodsId, isShowNo = true, text = string.format('%d', listData.num)})
    end
    local maxNode = cell.transform:Find('OverflowMax')
    local cardId = listData.data.vo.cardId
    CfUtils.SetActive(maxNode, self:CheckCoreMax(cardId))
    return cell
end

---刷新选中数量
function GroceryCoreExchangeDialog:RefreshSelectedNum()
    local scr = CfUtils.GetLuaScr(self.QuantitySlider, GroceryConstants.ScrPath.CommonSliderNode)

    local curNum = self:GetCurrentSelectedNum()
    scr:SetValue(curNum)

    local convertNum = 0
