    for k, v in pairs(self:GetSelectedCoreNum()) do
        convertNum = convertNum + checkInt(v) * checkInt(data[k].vo.effectNum)
    end
    CfUtils.SetActive(self.TextExchange, convertNum > 0)
    CfUtils.FillText(self.TextExchange, localize("可转换：_num_", {_num_ = convertNum}))
end

