---选中核心
---@param index integer 索引
---@param num integer 增加数量
function GroceryCoreExchangeDialog:SelectCore(index, num)
    local numList = self:GetSelectedCoreNum()
    local selectedNum = checkInt(numList[index])
    local max = self:GetSelectedCoreData()[index].num - selectedNum
    local delta = math.min(max, num)
    if numList[index] then
        numList[index] = selectedNum + delta
    else
        numList[index] = delta
    end
    self:RefreshSelectedState()
    local cell = self.ScrollView:GetShownItemByItemIndex(index - 1)
    local scr = self:GetCellScr(cell)
    if not isNull(scr) then
        scr:SetSelectedNum(numList[index])
    end
end

---取消选中核心
function GroceryCoreExchangeDialog:UnselectCore(index, num)
    local numList = self:GetSelectedCoreNum()
    local selectedNum = checkInt(numList[index])
    local delta = math.min(selectedNum, num)
    if numList[index] then
        if numList[index] - delta == 0 then
            numList[index] = nil
        else
            numList[index] = numList[index] - delta
        end
    end
    self:RefreshSelectedState()
    local cell = self.ScrollView:GetShownItemByItemIndex(index - 1)
    local scr = self:GetCellScr(cell)
    if not isNull(scr) then
        scr:SetSelectedNum(numList[index])
    end
end

---滑动条变动
function GroceryCoreExchangeDialog:SliderValueChanged(value)
    local curNum = self:GetCurrentSelectedNum()
    local changeValue = value - curNum
    local data = self:GetSelectedCoreData()
    local selectedNum = self:GetSelectedCoreNum()
    -- 更改选中核心
    if changeValue > 0 then
        -- 增加
        for i, v in ipairs(data) do
            if not BackpackComponent:IsGoodsLocked(v.goodsId) then
                local leftNum = checkInt(v.num) - checkInt(selectedNum[i])
                if leftNum > 0 then
                    if changeValue >= leftNum then
                        selectedNum[i] = checkInt(v.num)
                        changeValue = changeValue - leftNum
                    else
                        selectedNum[i] = checkInt(selectedNum[i]) + changeValue
                        changeValue = 0
                    end
                end
                if changeValue == 0 then
                    break
                end
            end
        end
    else
        -- 减少
        for i = #data, 1, -1 do
            if selectedNum[i] then
                if math.abs(changeValue) >= selectedNum[i] then
                    changeValue = changeValue + selectedNum[i]
                    selectedNum[i] = nil
                else
                    selectedNum[i] = selectedNum[i] + changeValue
                    changeValue = 0
                end
            end
            if changeValue == 0 then
                break
            end
        end
    end

    self:RefreshListView()
    self:RefreshSelectedState()
end

---检查核心对应卡牌是否升满
function GroceryCoreExchangeDialog:CheckCoreMax(cardId)
    if not CardComp:IsHasCard(cardId) then
        return false
    end

    local maxStar = checkNumber(cardConfMgr:GetCardProgressionParamsById(CardProgressionConstants.Params.MaxStar))
    local id = CardComp:GetIdByCardId(cardId)
    local cardDojo = CardComp:GetCardById(id)
    return checkInt(cardDojo.star) >= maxStar
end

